9		"fmt"
10		"io"
11		"strings"
12	
13		"github.com/entireio/cli/cmd/entire/cli/textutil"
14		"github.com/entireio/cli/cmd/entire/cli/transcript"
15	)
16	
17	// MetadataFields provides metadata fields written to every output line.
18	type MetadataFields struct {
19		Agent      string // e.g. "claude-code"
20		CLIVersion string // e.g. "0.42.0"
21		StartLine  int    // checkpoint_transcript_start (0 = no truncation)
22	}
23	
24	// transcriptLine is the uniform output format for every line in transcript.jsonl.
25	// Field order is guaranteed by encoding/json (struct declaration order).
26	type transcriptLine struct {
27		V            int             `json:"v"`
28		Agent        string          `json:"agent"`
29		CLIVersion   string          `json:"cli_version"`
30		Type         string          `json:"type"`
31		TS           json.RawMessage `json:"ts,omitempty"`
32		ID           string          `json:"id,omitempty"`
33		InputTokens  int             `json:"input_tokens,omitempty"`
34		OutputTokens int             `json:"output_tokens,omitempty"`
35		Content      json.RawMessage `json:"content"`
36	}
37	
38	// newTranscriptLine returns a transcriptLine pre-filled with the shared
39	// metadata fields that are identical on every output line.
40	func newTranscriptLine(opts MetadataFields) transcriptLine {
41		return transcriptLine{
42			V:          1,
43			Agent:      opts.Agent,
44			CLIVersion: opts.CLIVersion,
45		}
46	}
47	
48	const toolResultStatusError = "error"
49	
50	// toolResultJSON is the compact result object inlined into tool_use blocks.
51	type toolResultJSON struct {
52		Output     string              `json:"output"`
53		Status     string              `json:"status"`
54		File       *toolResultFileJSON `json:"file,omitempty"`
55		MatchCount int                 `json:"matchCount,omitempty"`
56	}
57	
58	// toolResultFileJSON carries structured file metadata from Read/Edit tool results.
59	type toolResultFileJSON struct {
60		FilePath string `json:"filePath"`
61		NumLines int    `json:"numLines,omitempty"`
62	}
63	
64	// userTextBlock is a text block within user message content.
65	type userTextBlock struct {
66		ID   string `json:"id,omitempty"`
67		Text string `json:"text"`
68	}
69	
70	// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
71	//
72	// The output format puts version, agent, and cli_version on every line,
73	// merges streaming assistant fragments with the same message ID, and inlines
74	// tool results into the preceding assistant's tool_use blocks:
75	//
76	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
77	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
78	func Compact(content []byte, opts MetadataFields) ([]byte, error) {
79		// Formats that need detection on raw content before line truncation:
80		// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
81		//   a JSON object mid-value. They handle StartLine as a message-index offset.
82		// - Codex: session_meta header is only on the first line. Codex handles
83		//   StartLine as a response_item index offset.
84		if isOpenCodeFormat(content) {
85			return compactOpenCode(content, opts)
86		}
87	
88		if isGeminiFormat(content) {
89			return compactGemini(content, opts)
90		}
91	
92		if isCodexFormat(content) {
93			return compactCodex(content, opts)
94		}
95	
96		truncated := transcript.SliceFromLine(content, opts.StartLine)
97		if truncated == nil {
98			truncated = []byte{}
99		}
100	
101		if isCopilotFormat(truncated) {
102			return compactCopilot(truncated, opts)
103		}
104	
105		if isDroidFormat(truncated) {
106			return compactDroid(truncated, opts)
107		}
108	
109		return compactJSONL(truncated, opts)
110	}
111	
112	// droppedTypes are JSONL entry types that carry no parser-relevant data.
113	var droppedTypes = map[string]bool{
114		"progress":              true,
115		"file-history-snapshot": true,
116		"queue-operation":       true,
117		"system":                true,
118	}
119	
120	// userAliases maps JSONL type/role values to the canonical "user" kind.
121	// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
122	var userAliases = map[string]bool{
123		transcript.TypeUser: true,
124		"human":             true,
125	}
126	
127	// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
128	// JSONL transcript line. It checks the "type" field, then falls back to "role".
129	// Returns "" for unrecognised or dropped entries.
130	func normalizeKind(raw map[string]json.RawMessage) string {
131		kind := unquote(raw["type"])
132		if kind == "" {
133			kind = unquote(raw["role"])
134		}
135	
136		if droppedTypes[kind] {
137			return ""
138		}
139		if userAliases[kind] {
140			return transcript.TypeUser
141		}
142		if kind == transcript.TypeAssistant {
143			return transcript.TypeAssistant
144		}
145		return ""
146	}
147	
148	// linePreprocessor transforms a parsed JSONL line before conversion.
149	type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
150	
151	// parsedEntry is an intermediate representation of a JSONL line used during
152	// the two-pass compact conversion.
153	type parsedEntry struct {
154		kind         string // "user" or "assistant"
155		ts           json.RawMessage
156		id           string            // message ID (assistant only)
157		userID       string            // prompt ID (user only, e.g. Claude's promptId)
158		inputTokens  int               // API input tokens (assistant only)
159		outputTokens int               // API output tokens (assistant only)
160		content      json.RawMessage   // stripped assistant content array, or nil
161		userText     string            // extracted user text
162		userImages   []json.RawMessage // image blocks from user messages
163		toolResults  []toolResultEntry // user tool_result entries
164	}
165	
166	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
167	// transcript.jsonl format.
168	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
169		return compactJSONLWith(content, opts, nil)
170	}
171	
172	func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
173		base := newTranscriptLine(opts)
174	
175		// Pass 1: parse all lines into intermediate entries.
176		entries, err := parseJSONLEntries(content, preprocess)
177		if err != nil {
178			return nil, err
179		}
180	
181		// Pass 2: merge and emit.
182		var result []byte
183		for i := 0; i < len(entries); i++ {
184			e := entries[i]
185	
186			switch e.kind {
187			case transcript.TypeAssistant:
188				// Merge consecutive assistant entries with the same message ID.
189				merged := e
190				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
191					i++
192					merged = mergeAssistantEntries(merged, entries[i])
193				}
194	
195				// Look ahead for user tool_result entries to inline.
196				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
197					userEntry := entries[i+1]
198					merged = inlineToolResults(merged, userEntry)
199					i++ // consume the user tool_result entry
200	
201					// If the consumed user entry also had text or image content, emit it
202					// as a separate user line after the assistant.
203					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
204						emitAssistant(&result, base, merged)
205						emitUser(&result, base, userEntry)
206						continue
207					}
208				}
209	
210				if isEmptyContentArray(merged.content) {
211					continue
212				}
213	
214				emitAssistant(&result, base, merged)
215	
216			case transcript.TypeUser:
217				// User entries that are purely tool results were already consumed
218				// by the assistant look-ahead above. If we reach one here it was
219				// not preceded by an assistant with a matching tool_use, so emit
220				// it only if it has text or image content.
221				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
222					continue
223				}
224				emitUser(&result, base, e)
225			}
226		}
227	
228		return result, nil
229	}
230	
231	func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
232		line := base
233		line.Type = transcript.TypeAssistant
234		line.TS = e.ts
235		line.ID = e.id
236		line.InputTokens = e.inputTokens
237		line.OutputTokens = e.outputTokens
238		line.Content = e.content
239		appendLine(result, line)
240	}
241	
242	func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
243		var blocks []json.RawMessage
244	
245		// Text block (with optional prompt ID).
246		if e.userText != "" || len(e.userImages) == 0 {
247			b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
248			if err != nil {
249				return
250			}
251			blocks = append(blocks, b)
252		}
253	
254		// Image blocks passed through verbatim.
255		blocks = append(blocks, e.userImages...)
256	
257		contentJSON, err := json.Marshal(blocks)
258		if err != nil {
259			return
260		}
261	
262		line := base
263		line.Type = transcript.TypeUser
264		line.TS = e.ts
265		line.Content = contentJSON
266		appendLine(result, line)
267	}
268	
269	// appendLine marshals a transcriptLine and appends it (with newline) to result.
270	func appendLine(result *[]byte, line transcriptLine) {
271		b, err := json.Marshal(line)
272		if err != nil {
273			return
274		}
275		*result = append(*result, b...)
276		*result = append(*result, '\n')
277	}
278	
279	// parseJSONLEntries parses all JSONL lines into intermediate entries,
280	// filtering dropped types and malformed lines.
281	func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
282		reader := bufio.NewReader(bytes.NewReader(content))
283		var entries []parsedEntry
284	
285		for {
286			lineBytes, err := reader.ReadBytes('\n')
287			if err != nil && err != io.EOF {
288				return nil, fmt.Errorf("reading JSONL line: %w", err)
289			}
290	
291			if len(bytes.TrimSpace(lineBytes)) > 0 {
292				if e, ok := parseLine(lineBytes, preprocess); ok {
293					entries = append(entries, e)
294				}
295			}
296	
297			if err == io.EOF {
298				break
299			}
300		}
301	
302		return entries, nil
303	}
304	
305	// parseLine converts a single JSONL line into a parsedEntry.
306	// Returns ok=false for dropped/malformed lines.
307	func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
308		var raw map[string]json.RawMessage
309		if err := json.Unmarshal(lineBytes, &raw); err != nil {
310			return parsedEntry{}, false
311		}
312	
313		if preprocess != nil {
314			raw = preprocess(raw)
315		}
316	
317		kind := normalizeKind(raw)
318		if kind == "" {
319			return parsedEntry{}, false
320		}
321	
322		e := parsedEntry{
323			kind: kind,
324			ts:   raw["timestamp"],
325		}
326	
327		msg := parseMessage(raw)
328	
329		switch kind {
330		case transcript.TypeAssistant:
331			if msg != nil {
332				e.id = unquote(msg["id"])
333				if contentRaw, ok := msg["content"]; ok {
334					e.content = stripAssistantContent(contentRaw)
335				}
336				e.inputTokens, e.outputTokens = extractUsageTokens(msg)
337			}
338	
339		case transcript.TypeUser:
340			e.userID = unquote(raw["promptId"])
341			if msg != nil {
342				if contentRaw, ok := msg["content"]; ok {
343					uc := extractUserContent(contentRaw)
344					e.userText = uc.text
345					e.userImages = uc.images
346					e.toolResults = uc.toolResults
347				}
348			}
349			// Enrich tool results with metadata from toolUseResult.
350			if turRaw, ok := raw["toolUseResult"]; ok {
351				var tur map[string]json.RawMessage
352				if json.Unmarshal(turRaw, &tur) == nil {
353					e.toolResults = enrichToolResults(e.toolResults, tur)
354				}
355			}
356		}
357	
358		return e, true
359	}
360	
361	// mergeAssistantEntries combines two assistant entries with the same message ID.
362	// Content arrays are concatenated; the later timestamp and token counts win
363	// (streaming fragments report cumulative usage, so the last fragment is final).
364	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
365		merged := a
366		merged.ts = b.ts
367		if b.inputTokens > 0 {
368			merged.inputTokens = b.inputTokens
369		}
370		if b.outputTokens > 0 {
371			merged.outputTokens = b.outputTokens
372		}
373	
374		var aBlocks, bBlocks []json.RawMessage
375		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
376		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
377		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
378		if data, err := json.Marshal(all); err == nil {
379			merged.content = data
380		}
381	
382		return merged
383	}
384	
385	// inlineToolResults adds "result" fields to matching tool_use blocks in the
386	// assistant entry's content, using outputs from user tool_result entries.
387	func inlineToolResults(assistant, user parsedEntry) parsedEntry {
388		var blocks []map[string]json.RawMessage
389		if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
390			return assistant
391		}
392	
393		for _, tr := range user.toolResults {
394			// Find the tool_use block matching this tool_use_id.
395			idx := -1
396			for i := len(blocks) - 1; i >= 0; i-- {
397				if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
398					if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
399						idx = i
400						break
401					}
402				}
403			}
404			// No matching tool_use block: do not attach a result to unrelated content.
405			if idx == -1 {
406				continue
407			}
408	
409			blocks[idx]["result"] = buildToolResult(tr)
410		}
411	
412		if data, err := json.Marshal(blocks); err == nil {
413			assistant.content = data
414		}
415	
416		return assistant
417	}
418	
419	// buildToolResult constructs the compact result object for a tool_use block,
420	// including optional rich metadata (file, matchCount) when available.
421	func buildToolResult(tr toolResultEntry) json.RawMessage {
422		r := toolResultJSON{
423			Output:     tr.output,
424			Status:     "success",
425			MatchCount: tr.matchCount,
426		}
427		if tr.isError {
428			r.Status = toolResultStatusError
429		}
430		if tr.file != nil {
431			r.File = &toolResultFileJSON{
432				FilePath: tr.file.filePath,
433				NumLines: tr.file.numLines,
434			}
435		}
436		b, err := json.Marshal(r)
437		if err != nil {
438			return nil
439		}
440		return b
441	}
442	
443	// extractUsageTokens extracts input_tokens and output_tokens from a Claude
444	// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
445	func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
446		usageRaw, ok := msg["usage"]
447		if !ok {
448			return 0, 0
449		}
450		var usage struct {
451			InputTokens  int `json:"input_tokens"`
452			OutputTokens int `json:"output_tokens"`
453		}
454		if json.Unmarshal(usageRaw, &usage) != nil {
455			return 0, 0
456		}
457		return usage.InputTokens, usage.OutputTokens
458	}
459	
460	// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
461	func isEmptyContentArray(raw json.RawMessage) bool {
462		var arr []json.RawMessage
463		return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
464	}
465	
466	func hasToolResults(e parsedEntry) bool {
467		return len(e.toolResults) > 0
468	}
469	
470	type toolResultEntry struct {
471		toolUseID string
472		output    string
473		isError   bool
474		// Rich metadata extracted from toolUseResult (optional).
475		file       *toolResultFile // Read/Edit: file path and line count
476		matchCount int             // Grep: number of matching files
477	}
478	
479	// toolResultFile carries structured file metadata from Read/Edit tool results.
480	type toolResultFile struct {
481		filePath string
482		numLines int // 0 if not available (e.g. Edit results)
483	}
484	
485	// enrichToolResults extracts structured metadata from a toolUseResult envelope
486	// and attaches it to the corresponding tool result entries.
487	//
488	// Claude Code's toolUseResult has different shapes per tool:
489	//   - Bash:  {stdout, stderr, interrupted, ...}
490	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
491	//   - Grep:  {numFiles, numLines, filenames, content, mode}
492	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
493	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
494		// Bash-style: stdout provides the output text.
495		if stdout := unquote(tur["stdout"]); stdout != "" {
496			switch len(results) {
497			case 0:
498				// Keep compatibility with transcripts that only include toolUseResult.
499				results = append(results, toolResultEntry{output: stdout})
500			case 1:
501				results[0].output = stdout
502			}
503		}
504	
505		// Read-style: file object with filePath and numLines.
506		if fileRaw, ok := tur["file"]; ok {
507			var file struct {
508				FilePath string `json:"filePath"`
509				NumLines int    `json:"numLines"`
510			}
511			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
512				applyToSingleResult(results, func(tr *toolResultEntry) {
513					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
514				})
515			}
516		}
517	
518		// Edit-style: top-level filePath.
519		if filePath := unquote(tur["filePath"]); filePath != "" {
520			applyToSingleResult(results, func(tr *toolResultEntry) {
521				// Edit results don't have numLines.
522				tr.file = &toolResultFile{filePath: filePath}
523			})
524		}
525	
526		// Grep-style: numFiles as match count.
527		if numFilesRaw, ok := tur["numFiles"]; ok {
528			var n int
529			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
530				applyToSingleResult(results, func(tr *toolResultEntry) {
531					tr.matchCount = n
532				})
533			}
534		}
535	
536		return results
537	}
538	
539	// applyToSingleResult applies fn to the first (and expected only) tool result.
540	// toolUseResult is a single-tool envelope, so this is only meaningful when
541	// there's exactly one result entry.
542	func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
543		if len(results) == 1 {
544			fn(&results[0])
545		}
546	}
547	
548	// parseMessage extracts and parses the "message" field from a JSONL transcript
549	// line. All JSONL agents nest content inside a "message" object.
550	func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
551		msgRaw, ok := raw["message"]
552		if !ok {
553			return nil
554		}
555		var msg map[string]json.RawMessage
556		if json.Unmarshal(msgRaw, &msg) == nil {
557			return msg
558		}
559		return nil
560	}
561	
562	// userContent holds the extracted parts of a user message content array.
563	type userContent struct {
564		text        string
565		images      []json.RawMessage
566		toolResults []toolResultEntry
567	}
568	
569	// extractUserContent separates user message content into text, images, and tool_result entries.
570	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
571	func extractUserContent(contentRaw json.RawMessage) userContent {
572		var str string
573		if json.Unmarshal(contentRaw, &str) == nil {
574			return userContent{text: textutil.StripIDEContextTags(str)}
575		}
576	
577		var blocks []json.RawMessage
578		if json.Unmarshal(contentRaw, &blocks) != nil {
579			return userContent{}
580		}
581	
582		var uc userContent
583	
584		for _, blockRaw := range blocks {
585			var block map[string]json.RawMessage
586			if json.Unmarshal(blockRaw, &block) != nil {
587				continue
588			}
589			blockType := unquote(block["type"])
590	
591			switch blockType {
592			case "tool_result":
593				var isErr bool
594				if raw, ok := block["is_error"]; ok {
595					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
596				}
597				uc.toolResults = append(uc.toolResults, toolResultEntry{
598					toolUseID: unquote(block["tool_use_id"]),
599					output:    unquote(block["content"]),
600					isError:   isErr,
601				})
602	
603			case "image":
604				uc.images = append(uc.images, blockRaw)
605	
606			case transcript.ContentTypeText:
607				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
608				if stripped != "" {
609					uc.text += stripped + "\n\n"
610				}
611			}
612		}
613	
614		uc.text = strings.TrimSpace(uc.text)
615		return uc
616	}
617	
618	func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
619		var str string
620		if json.Unmarshal(contentRaw, &str) == nil {
621			return contentRaw
622		}
623	
624		var blocks []map[string]json.RawMessage
625		if json.Unmarshal(contentRaw, &blocks) != nil {
626			return contentRaw
627		}
628	
629		result := make([]map[string]json.RawMessage, 0, len(blocks))
630		for _, block := range blocks {
631			blockType := unquote(block["type"])
632	
633			if blockType == "thinking" || blockType == "redacted_thinking" {
634				continue
635			}
636	
637			if blockType == transcript.ContentTypeToolUse {
638				stripped := make(map[string]json.RawMessage)
639				copyField(stripped, block, "type")
640				copyField(stripped, block, "id")
641				copyField(stripped, block, "name")
642				copyField(stripped, block, "input")
643				result = append(result, stripped)
644				continue
645			}
646	
647			result = append(result, block)
648		}
649	
650		b, err := json.Marshal(result)
651		if err != nil {
652			return contentRaw
653		}
654		return b
655	}
656	
657	// copyField copies a single key from src to dst if it exists.
658	func copyField(dst, src map[string]json.RawMessage, key string) {
659		if v, ok := src[key]; ok {
660			dst[key] = v
661		}
662	}
663	
664	// unquote JSON-decodes a raw message as a string. Returns "" on failure.
665	func unquote(raw json.RawMessage) string {
666		var s string
667		if json.Unmarshal(raw, &s) == nil {
668			return s
669		}
670		return ""
671	}
