65	// and the raw transcript (full.jsonl) from /full/* refs (current + archived generations).
66	// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
67	// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
68	// Returns ErrNoTranscript if the session exists but no raw transcript is available.
69	// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
70	func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
71		if err := ctx.Err(); err != nil {
72			return nil, err //nolint:wrapcheck // Propagating context cancellation
73		}
74	
75		refName := plumbing.ReferenceName(paths.V2MainRefName)
76		_, rootTreeHash, err := s.GetRefState(refName)
77		if err != nil {
78			return nil, ErrCheckpointNotFound
79		}
80	
81		rootTree, err := s.repo.TreeObject(rootTreeHash)
82		if err != nil {
83			return nil, ErrCheckpointNotFound
84		}
85	
86		cpTree, err := rootTree.Tree(checkpointID.Path())
87		if err != nil {
88			return nil, ErrCheckpointNotFound
89		}
90	
91		sessionDir := strconv.Itoa(sessionIndex)
92		sessionTree, err := cpTree.Tree(sessionDir)
93		if err != nil {
94			return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
95		}
96	
97		result := &SessionContent{}
98	
99		if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
100			if content, contentErr := metadataFile.Contents(); contentErr == nil {
101				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
102					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
103				}
104			}
105		}
106	
107		if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
108			if content, contentErr := file.Contents(); contentErr == nil {
109				result.Prompts = content
110			}
111		}
112	
113		transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
114		if transcriptErr != nil {
115			return nil, fmt.Errorf("failed to read transcript from /full/* refs: %w", transcriptErr)
116		}
117		if len(transcript) == 0 {
118			return nil, ErrNoTranscript
119		}
120		result.Transcript = transcript
121	
122		return result, nil
123	}
